eventScripts.script:
if currentValue.value ==False and previousValue.value ==True :
	tagpath=["[.]../Machineinfo/MachineID","[.]Ongoingbreakdown","[~]Current_Shift/Start_time", "[.]Planned_downtime"]
	tagvalue=system.tag.readBlocking(tagpath)
	Ongoingbreakdown=tagvalue[1].value
	plannedDt = tagvalue[3].value
	if Ongoingbreakdown and plannedDt:
		MachineID=tagvalue[0].value
		parameters={"MachineID":MachineID}
		CurrentData = system.db.runNamedQuery("downtime/Active_downtime", parameters)
		if CurrentData.getRowCount() > 0:
			DowntimeSource=CurrentData.getValueAt(0,"DowntimeSource")
			if DowntimeSource==0:
				EndTime=tagvalue[2].value
				LogID=CurrentData.getValueAt(0,"LogID")
				parameters = {"EndTime":system.date.now(),"LogID":LogID}
				system.db.runNamedQuery("downtime/UpdateDowntimeCompletion", parameters)
				system.tag.writeBlocking(["[.]../Downtime/Ongoingbreakdown"], [False])

blockTagPath = "[.]../Machine Block/MachineBlock"
if currentValue.value == True:
	system.tag.writeBlocking(blockTagPath, False)
else:
	sessionStatus = system.tag.readBlocking("[.]../Session_status/Session_Active")[0].value
	if not sessionStatus:
		system.tag.writeBlocking(blockTagPath, True)

sup_MachineOveride = system.tag.readBlocking("[.]../Machine Block/MachineBlockOveride")[0].value
ongoingDT = system.tag.readBlocking("[.]../Downtime/Ongoingbreakdown")[0].value
if not sup_MachineOveride:
	blockTagPath = "[.]../Machine Block/MachineBlock"
	if currentValue.value == True and not ongoingDT:
		system.tag.writeBlocking(blockTagPath, False)
	elif currentValue.value == False:
		system.tag.writeBlocking(blockTagPath, True)

if currentValue.value:
	path = "[.]../Session_status/LastUserActive"
	system.tag.writeBlocking(path, "")
	tagpath=["[.]../WO/PO","[.]../WO/serial_number","[.]../ProductionData/WIP","[~]Current_Shift/Old_shift_ID"]
	tagvalue=system.tag.readBlocking(tagpath)
	PO=tagvalue[0].value
	SerialNumber=tagvalue[1].value
	WIP=tagvalue[2].value
	ShiftID=tagvalue[3].value
	if PO is not None:
		params={"PO": PO,"SerialNumber":SerialNumber ,"WIP": WIP,"ShiftID":ShiftID}
		NQ='downtime/ShiftChangeData'
		system.db.runNamedQuery(NQ,params)
elif currentValue.value ==False and previousValue.value ==True :
	tagpath=["[.]../Machineinfo/MachineID","[.]../Downtime/Ongoingbreakdown","[~]Current_Shift/Start_time"]
	tagvalue=system.tag.readBlocking(tagpath)
	Ongoingbreakdown=tagvalue[1].value
	if Ongoingbreakdown:
		MachineID=tagvalue[0].value
		parameters={"MachineID":MachineID}
		CurrentData = system.db.runNamedQuery("downtime/Active_downtime", parameters)
		if CurrentData.getRowCount() > 0:
			DowntimeSource=CurrentData.getValueAt(0,"DowntimeSource")
			if DowntimeSource==0:
				EndTime=tagvalue[2].value
				LogID=CurrentData.getValueAt(0,"LogID")
				parameters = {"EndTime":EndTime,"LogID":LogID}
				system.db.runNamedQuery("downtime/UpdateDowntimeCompletion", parameters)
				system.tag.writeBlocking(["[.]../Downtime/Ongoingbreakdown","[.]../Downtime/Manual_entry_Active"], [False,False])
				#pass

